{"code_completion": "module TopModule (
    input  clk,
    input  reset,
    input  in,
    output out
);

    // state: 1'b1 = B (out=1), 1'b0 = A (out=0)
    reg state;

    always @(posedge clk) begin
        if (reset)
            state <= 1'b1;       // reset state is B
        else if (!in)
            state <= ~state;     // toggle on in=0
        // if in=1, stay in current state
    end

    assign out = state;

endmodule"}
